import urllib.request,urllib.parse,json
params={'Symbol':'فملی','Category':'1','LetterType':'-1','PageNumber':'1','search':'true','Childs':'false','Mains':'true','Publisher':'false','Audited':'true','NotAudited':'true','Consolidatable':'true','NotConsolidatable':'true'}
url='https://search.codal.ir/api/search/v2/q?'+urllib.parse.urlencode(params)
req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0','Accept':'application/json'})
try:
 d=json.loads(urllib.request.urlopen(req,timeout=20).read().decode('utf-8'))
 print('TOTAL',d.get('Total'),'PAGE',d.get('Page'),'COUNT',len(d.get('Letters',[])))
 for x in d.get('Letters',[])[:15]: print(json.dumps({k:x.get(k) for k in ['TracingNo','Symbol','Title','LetterCode','PublishDateTime','Url']},ensure_ascii=False))
except Exception as e: print('ERROR',type(e).__name__,str(e)[:500])
